<template><view class="page">
  <view class="nav"><view class="back-button" @click="back">‹ {{ tr('Back') }}</view><text>{{ tr('Device Management') }}</text><text class="refresh" @click="load">↻</text></view>
  <view class="hero"><view class="hero-copy"><text>{{ tr('Your monitoring devices') }}</text><text>{{ tr('Keep your measurements connected') }}</text></view><view class="hero-device">⌁</view><view class="hero-bottom"><text>{{ devices.length }} {{ tr('bound devices') }}</text><text>{{ devices.filter(d=>d.isConnected).length }} {{ tr('Online') }}</text></view></view>
  <view class="section-heading"><text>{{ tr('My Devices') }}</text><text class="muted">{{ tr('Select a device for your data') }}</text></view>
  <view v-if="!devices.length" class="empty"><text>⌁</text><text>{{ tr('No devices bound yet') }}</text><text class="muted">{{ tr('Add your device below to get started') }}</text></view>
  <view v-for="(device,index) in devices" :key="device.deviceId" class="device-card" :class="{selected:selected===device.deviceId}">
    <view class="device-top"><view class="device-icon">⌁</view><view class="device-name"><text>{{ tr('Device') }} {{ index+1 }}</text><text class="muted">{{ tr('Device number') }} · {{ uiLang==='en'?device.deviceId:(device.deviceId.split('_').pop().replace(/[^0-9]/g,'')||'—') }}</text></view><text class="state" :class="{online:device.isConnected}"><text>● </text>{{ tr(device.isConnected?'Online':'Offline') }}</text></view>
    <view class="device-note"><view class="status-dot"/><text>{{ device.lastActive ? (uiLang==='zh'?'最近测量：':'Latest measurement: ') + formatTime(device.lastActive) : (uiLang==='zh'?'尚无测量记录':'No measurements yet') }}</text></view>
    <view class="actions"><view class="select-button" :class="{active:selected===device.deviceId}" @click="select(device.deviceId)">{{ selected===device.deviceId?'✓ ':'' }}{{ tr(selected===device.deviceId?'Selected':'Select') }}</view><view class="unbind" @click="unbind(device.deviceId)">{{ tr('Unbind') }}</view></view>
  </view>
  <view class="section-heading"><text>{{ tr('Add a device') }}</text><text class="add-icon">+</text></view>
  <view class="bind-card"><text class="bind-title">{{ tr('Bind by device number') }}</text><text class="muted">{{ tr('Enter the exact device number printed on your device. Automatic discovery is not available yet.') }}</text><view class="input-box"><text>⌗</text><input v-model="newDeviceId" :placeholder="tr('Device number')" :maxlength="64" /></view><button class="bind-button" @click="bind" :disabled="busy" :loading="busy">{{ tr('Bind Device') }}</button></view>
  <view class="help"><view>ⓘ</view><text>{{ uiLang==='zh'?'在线表示最近 5 分钟内有新的测量结果；解绑不会删除历史数据。':'Online means a measurement was saved in the last 5 minutes. Unbinding keeps saved history.' }}</text></view>
</view></template>
<script>
import {backToTab} from '@/utils/navigation.js';
import {getAuthUrl} from '@/config/api.js';
export default {
  data:()=>({devices:[],newDeviceId:'',selected:'',busy:false}),
  onShow(){this.load();},
  methods:{
    back(){backToTab('profile');},
    formatTime(value){const d=new Date(value);if(!Number.isFinite(d.getTime()))return String(value||'--');return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')} ${String(d.getHours()).padStart(2,'0')}:${String(d.getMinutes()).padStart(2,'0')}`;},
    normalize(row){const deviceId=row.deviceId||row.device_id||'';const lastActive=row.lastActive||row.last_active||null;const time=lastActive?new Date(lastActive).getTime():NaN;return {...row,deviceId,deviceName:row.deviceName||row.device_name||deviceId,lastActive,isConnected:Number.isFinite(time)&&Date.now()-time<5*60*1000};},
    load(){uni.request({url:getAuthUrl('devices'),success:r=>{if(r.data.errcode===0){this.devices=(r.data.data||[]).map(this.normalize);const stored=uni.getStorageSync('selectedDeviceId');this.selected=this.devices.some(d=>d.deviceId===stored)?stored:(this.devices[0]?.deviceId||'');if(this.selected)uni.setStorageSync('selectedDeviceId',this.selected);else uni.removeStorageSync('selectedDeviceId');}},fail:()=>this.error()});},
    error(){uni.showToast({title:this.tr('Network error'),icon:'none'});},
    select(id){this.selected=id;uni.setStorageSync('selectedDeviceId',id);uni.showToast({title:this.tr('Selected'),icon:'success'});},
    bind(){const id=this.newDeviceId.trim();if(!/^[A-Za-z0-9_-]{1,64}$/.test(id)){uni.showToast({title:this.tr('Enter a valid device number'),icon:'none'});return;}this.busy=true;uni.request({url:getAuthUrl('devicesBind'),method:'POST',data:{deviceId:id},success:r=>{if(r.data.errcode===0||r.data.errcode===2){this.select(id);this.newDeviceId='';this.load();uni.showToast({title:this.tr(r.data.errcode===0?'Bound':'Selected'),icon:'success'});}else uni.showToast({title:this.tr(r.data.msg),icon:'none'});},fail:()=>this.error(),complete:()=>{this.busy=false;}});},
    unbind(id){uni.showModal({title:this.tr('Unbind'),content:this.tr('Unbind this device? Historical measurements will be kept.'),success:r=>{if(!r.confirm)return;uni.request({url:getAuthUrl('devices')+'/'+encodeURIComponent(id),method:'DELETE',success:r=>{if(r.data.errcode===0){if(this.selected===id)uni.removeStorageSync('selectedDeviceId');this.load();}else uni.showToast({title:this.tr(r.data.msg),icon:'none'});},fail:()=>this.error()});}});}
  }
};
</script>
<style scoped>
.page{background:#f5f6fb;min-height:100vh;padding:28rpx 28rpx calc(60rpx + env(safe-area-inset-bottom));box-sizing:border-box;color:#29344c}.nav{display:flex;align-items:center;justify-content:space-between;padding:12rpx 0 30rpx;font-size:27rpx}.nav>text:first-of-type{font-size:32rpx;font-weight:700}.back-button{padding:18rpx 18rpx 18rpx 0;min-width:100rpx}.refresh{font-size:42rpx;color:#8b76d9}.hero{position:relative;background:linear-gradient(120deg,#7364db,#957ce7);color:white;padding:34rpx;border-radius:30rpx;margin-bottom:26rpx}.hero-copy>text{display:block}.hero-copy>text:first-child{font-size:34rpx;font-weight:700;max-width:80%}.hero-copy>text:last-child{font-size:22rpx;opacity:.8;margin-top:14rpx;max-width:80%}.hero-device{position:absolute;right:34rpx;top:30rpx;font-size:80rpx;opacity:.6}.hero-bottom{display:flex;justify-content:space-between;border-top:1px solid #ffffff30;padding-top:22rpx;margin-top:32rpx;font-size:24rpx;color:#ffffffd0}.measurement-user-note{display:flex;gap:18rpx;background:#eeeafa;color:#7462bb;border-radius:22rpx;padding:24rpx;margin-bottom:32rpx}.measurement-user-note>text{font-size:38rpx}.measurement-user-note view text{display:block}.measurement-user-note view text:first-child{font-size:25rpx;font-weight:600}.measurement-user-note view text:last-child{font-size:21rpx;line-height:1.6;margin-top:7rpx;color:#9789be}.section-heading{display:flex;align-items:center;justify-content:space-between;margin:30rpx 6rpx 22rpx;font-size:30rpx;font-weight:600}.muted{font-size:22rpx;color:#9aa2b4;line-height:1.6;font-weight:400}.device-card{background:white;border:2rpx solid transparent;border-radius:28rpx;padding:28rpx;margin-bottom:22rpx}.device-card.selected{border-color:#c6b8ee;box-shadow:0 6rpx 24rpx #8470cb09}.device-top{display:flex;align-items:center;gap:20rpx}.device-icon{width:80rpx;height:80rpx;line-height:80rpx;text-align:center;background:#f1edfc;color:#9278dd;font-size:58rpx;border-radius:23rpx}.device-name{flex:1;min-width:0}.device-name>text{display:block}.device-name>text:first-child{font-size:30rpx;font-weight:600;margin-bottom:6rpx}.state{padding:10rpx 14rpx;background:#f3f4f7;color:#9aa3b3;font-size:21rpx;border-radius:13rpx;white-space:nowrap}.state.online{background:#eaf7f1;color:#62ae94}.device-note{display:flex;align-items:center;gap:12rpx;margin:24rpx 0;font-size:22rpx;color:#9ba4b5}.status-dot{height:9rpx;width:9rpx;border-radius:50%;background:#b5bdcc}.actions{display:flex;align-items:center;gap:20rpx;border-top:1px solid #f3f4f8;padding-top:22rpx}.select-button{flex:1;background:#f5f6fa;color:#a0a8b8;border-radius:17rpx;padding:17rpx;text-align:center;font-size:24rpx}.select-button.active{background:#efebfa;color:#8e73d7}.unbind{padding:14rpx;color:#b19199;font-size:24rpx}.add-icon{font-size:38rpx;color:#9b85dc}.bind-card{background:white;padding:30rpx;border-radius:28rpx}.bind-title{display:block;font-size:29rpx;font-weight:600;margin-bottom:12rpx}.bind-card>.muted{display:block}.input-box{display:flex;align-items:center;gap:18rpx;margin:26rpx 0;background:#f7f8fb;border-radius:18rpx;padding:20rpx;color:#a4acbb}.input-box>text{font-size:34rpx}.input-box input{flex:1;min-width:0;font-size:26rpx;color:#56627c;height:46rpx}.bind-button{padding:18rpx;border-radius:18rpx;background:#826cdb;color:white;font-size:27rpx}.bind-button:after{border:0}.help{display:flex;gap:16rpx;color:#a2aabb;font-size:22rpx;line-height:1.8;margin:28rpx 10rpx}.help>view{font-size:30rpx;color:#aa99d4}.empty{text-align:center;background:white;border-radius:26rpx;padding:45rpx 24rpx}.empty>text{display:block;margin:10rpx 0;font-size:26rpx}.empty>text:first-child{font-size:70rpx;color:#b6a6e9}
</style>
